aScript-এর সিনট্যাক্স ও `validate.py` যাচাই করেছি, কিন্তু ব্রাউজারে খুলে দেখিনি। `assets/logo.png` আমার এখানে নেই, তাই লোগো আপনার লোকালে দেখে নিন।\n\n1. **লোগো:** \"M\" ফ্যালব্যাক পুরোপুরি বাদ। হেডার ও স্প্ল্যাশ দুই জায়গায় সরাসরি `meta.logo` (`assets/logo.png`) লিংক থেকে লোগো লোড হয়।\n2. **EN | BN টগল:** হেডারে বোতাম যোগ হয়েছে, ডিফল্ট EN। BN বেছে নিলে মেনু, ড্যাশবোর্ড, স্ট্যাটাস, ফিল্টার, বিস্তারিত প্যানেল, ফুটার, তারিখ ও শিরোনাম (`title_bn` থাকলে) বাংলায় দেখায়। পছন্দ মনে থাকে, পরের বার খুললে একই ভাষা থাকবে।\n3. **ফুটার:** সেখানে আপনার চলমান প্রজেক্ট, ওয়েবসাইট, ইমেইল ও লিংকডিনের লিংক আছে। এর নিচে \"Quick commands & emergency help\" ভাঁজ করা অংশে সব শেল কমান্ড আছে। কমান্ডে ক্লিক করলে কপি হয়। জরুরি অবস্থায় `data.json.bak` থেকে ফেরত আনার কমান্ডও আছে।\n4. **ট্যাগলাইন:** আপনার লাইনটি স্প্ল্যাশ স্ক্রিন ও ফুটারে বসিয়েছি।\n\nফুটারের লিংক, কমান্ড ও ট্যাগলাইন সবই `data.json`-এর `meta.links`, `meta.commands` ও `meta.tagline` থেকে আসে। ভবিষ্যতে এগুলো বদলাতে শুধু `data.json` এডিট করলেই হবে, `index.html` ছুঁতে হবে না।\n\n---\n\n## V1.2\n\n`add_task.py`\n```\n#!/usr/bin/env python3\n\"\"\"python3 add_task.py \"Title\" [--bn \"শিরোনাম\"] [--desc ..] [--priority low|medium|high|urgent] [--due YYYY-MM-DD] [--category ..] [--tags a,b]\"\"\"\nimport argparse\nfrom _lib import *\na = argparse.ArgumentParser()\na.add_argument(\"title\", nargs=\"?\", default=\"\"); a.add_argument(\"--bn\", default=\"\"); a.add_argument(\"--desc\", default=\"\")\na.add_argument(\"--priority\", default=\"medium\", choices=[\"low\", \"medium\", \"high\", \"urgent\"])\na.add_argument(\"--due\", default=\"\"); a.add_argument(\"--category\", default=\"general\"); a.add_argument(\"--tags\", default=\"\")\nx = a.parse_args()\nif not x.title:\n    print(\"— New task (Enter to skip optional fields) —\")\n    x.title = ask(\"Title (EN) *\", req=True); x.bn = ask(\"শিরোনাম (BN)\"); x.desc = ask(\"Description\")\n    x.priority = ask(\"Priority low/medium/high/urgent\", \"medium\", choices=[\"low\", \"medium\", \"high\", \"urgent\"])\n    x.due = ask(\"Due YYYY-MM-DD\"); x.category = ask(\"Category\", \"general\"); x.tags = ask(\"Tags a,b\")\nd = load(); i = next_id(d, \"task\")\nd[\"tasks\"].append({\"id\": i, \"title\": x.title, \"title_bn\": x.bn, \"desc\": x.desc, \"status\": \"todo\",\n  \"priority\": x.priority, \"due\": x.due, \"category\": x.category, \"tags\": tags(x.tags),\n  \"created_at\": now(), \"completed_at\": \"\", \"history\": [{\"at\": now(), \"event\": \"created\"}]})\nsave(d); print(\"✔ Task added:\", i)\n```\n\n---\n\n`add_note.py`\n```\n#!/usr/bin/env python3\n\"\"\"python3 add_note.py \"Title\" [--bn ..] [--body ..] [--category ..] [--tags a,b] [--pinned]\"\"\"\nimport argparse\nfrom _lib import *\na = argparse.ArgumentParser()\na.add_argument(\"title\", nargs=\"?\", default=\"\"); a.add_argument(\"--bn\", default=\"\"); a.add_argument(\"--body\", default=\"\")\na.add_argument(\"--category\", default=\"general\"); a.add_argument(\"--tags\", default=\"\"); a.add_argument(\"--pinned\", action=\"store_true\")\nx = a.parse_args()\nif not x.title:\n    print(\"— New note (Enter to skip optional fields) —\")\n    x.title = ask(\"Title (EN) *\", req=True); x.bn = ask(\"শিরোনাম (BN)\"); x.body = ask(\"Body\")\n    x.category = ask(\"Category\", \"general\"); x.tags = ask(\"Tags a,b\"); x.pinned = ask(\"Pin? y/n\", \"n\", choices=[\"y\", \"n\"]) == \"y\"\nd = load(); i = next_id(d, \"note\")\nd[\"notes\"].append({\"id\": i, \"title\": x.title, \"title_bn\": x.bn, \"body\": x.body, \"category\": x.category,\n  \"tags\": tags(x.tags), \"pinned\": x.pinned, \"created_at\": now(), \"history\": [{\"at\": now(), \"event\": \"created\"}]})\nsave(d); print(\"✔ Note added:\", i)\n```\n\n---\n\n`add_audit.py`\n```\n#!/usr/bin/env python3\n\"\"\"python3 add_audit.py \"Title\" --result pass|warning|fail [--target ..] [--findings ..] [--auditor ..] [--related TSK-2026-0001,NOT-..] [--bn ..] [--category ..] [--tags ..]\"\"\"\nimport argparse\nfrom _lib import *\na = argparse.ArgumentParser()\na.add_argument(\"title\", nargs=\"?\", default=\"\"); a.add_argument(\"--bn\", default=\"\"); a.add_argument(\"--result\", default=\"\", choices=[\"pass\", \"warning\", \"fail\"])\na.add_argument(\"--target\", default=\"\"); a.add_argument(\"--findings\", default=\"\"); a.add_argument(\"--auditor\", default=\"\")\na.add_argument(\"--related\", default=\"\"); a.add_argument(\"--category\", default=\"general\"); a.add_argument(\"--tags\", default=\"\")\nx = a.parse_args()\nif not x.title:\n    print(\"— New audit (Enter to skip optional fields) —\")\n    x.title = ask(\"Title (EN) *\", req=True); x.bn = ask(\"শিরোনাম (BN)\")\n    x.result = ask(\"Result pass/warning/fail *\", req=True, choices=[\"pass\", \"warning\", \"fail\"])\n    x.target = ask(\"Target\"); x.findings = ask(\"Findings\"); x.auditor = ask(\"Auditor\", \"MJ Ahmad\")\n    x.related = ask(\"Related IDs a,b\"); x.category = ask(\"Category\", \"general\"); x.tags = ask(\"Tags a,b\")\nif not x.result: die(\"--result is required (pass|warning|fail)\")\nd = load()\nfor r in tags(x.related):\n    if find(d, r)[0] is None: die(f\"related ID not found: {r}\")\ni = next_id(d, \"audit\")\nd[\"audits\"].append({\"id\": i, \"title\": x.title, \"title_bn\": x.bn, \"result\": x.result, \"target\": x.target,\n  \"findings\": x.findings, \"auditor\": x.auditor, \"related\": tags(x.related), \"category\": x.category,\n  \"tags\": tags(x.tags), \"created_at\": now(), \"history\": [{\"at\": now(), \"event\": \"created\"}]})\nsave(d); print(\"✔ Audit added:\", i)\n```\n\n---\n\n`complete_task.py`\n```\n#!/usr/bin/env python3\n\"\"\"python3 complete_task.py TSK-2026-0001 [--note \"...\"] [--status doing|done|todo]\"\"\"\nimport argparse\nfrom _lib import *\na = argparse.ArgumentParser(); a.add_argument(\"id\", nargs=\"?\", default=\"\"); a.add_argument(\"--note\", default=\"\")\na.add_argument(\"--status\", default=\"done\", choices=[\"todo\", \"doing\", \"done\"])\nx = a.parse_args(); d = load()\nif not x.id:\n    for t in d[\"tasks\"]:\n        if t[\"status\"] != \"done\": print(f'  {t[\"id\"]}  [{t[\"status\"]}]  {t[\"title\"]}')\n    x.id = ask(\"Task ID *\", req=True); x.note = ask(\"Note\"); k, t = find(d, x.id)\nif k != \"task\": die(f\"task not found: {x.id}\")\nt[\"status\"] = x.status; t[\"completed_at\"] = now() if x.status == \"done\" else \"\"\nt[\"history\"].append({\"at\": now(), \"event\": \"status → \" + x.status, \"note\": x.note})\nsave(d); print(f\"✔ {x.id} → {x.status}\")\n```\n\n---\n\n`_lib.py`\n```\n#!/usr/bin/env python3\n\"\"\"Shared helpers: load/save data.json safely, unique IDs, history log.\"\"\"\nimport json, os, shutil, sys\nfrom datetime import datetime\nHERE = os.path.dirname(os.path.abspath(__file__))\nDATA = os.path.join(HERE, \"data.json\")\nKIND = {\"task\": (\"TSK\", \"tasks\"), \"note\": (\"NOT\", \"notes\"), \"audit\": (\"AUD\", \"audits\"), \"code\": (\"CDE\", \"codes\")}\n\ndef now(): return datetime.now().astimezone().isoformat(timespec=\"seconds\")\n\ndef load():\n    with open(DATA, encoding=\"utf-8\") as f: d = json.load(f)\n    d.setdefault(\"codes\", []); return d\n\ndef save(d):\n    d[\"meta\"][\"updated_at\"] = now()\n    if os.path.exists(DATA): shutil.copy(DATA, DATA + \".bak\")\n    tmp = DATA + \".tmp\"\n    with open(tmp, \"w\", encoding=\"utf-8\") as f:\n        json.dump(d, f, ensure_ascii=False, indent=2)\n    os.replace(tmp, DATA)\n\ndef next_id(d, kind):\n    \"\"\"Never reuses an ID: PREFIX-YYYY-NNNN, counter kept per kind & year.\"\"\"\n    p, _ = KIND[kind]; y = datetime.now().year\n    c = d[\"meta\"].setdefault(\"counters\", {}).setdefault(kind, {})\n    c[str(y)] = c.get(str(y), 0) + 1\n    return f\"{p}-{y}-{c[str(y)]:04d}\"\n\ndef find(d, id_):\n    for k, (p, key) in KIND.items():\n        for it in d[key]:\n            if it[\"id\"] == id_: return k, it\n    return None, None\n\ndef tags(s): return [t.strip() for t in (s or \"\").split(\",\") if t.strip()]\n\ndef die(msg): print(\"ERROR:\", msg, file=sys.stderr); sys.exit(1)\n\ndef ask(label, default=\"\", req=False, choices=None):\n    \"\"\"Interactive prompt used when a script runs without arguments.\"\"\"\n    while True:\n        v = input(f\"{label}{' ['+default+']' if default else ''}: \").strip() or default\n        if req and not v: print(\"  required\"); continue\n        if choices and v not in choices: print(\"  choose:\", \"/\".join(choices)); continue\n        return v\n\nimport hashlib\nEXT = {\"html\":(\"html\",\"HTML\"),\"htm\":(\"html\",\"HTML\"),\"json\":(\"json\",\"JSON\"),\"py\":(\"python\",\"Python\"),\n \"js\":(\"node\",\"Node.js\"),\"mjs\":(\"node\",\"Node.js\"),\"cjs\":(\"node\",\"Node.js\"),\"ts\":(\"ts\",\"TypeScript\"),\n \"jsx\":(\"react\",\"React\"),\"tsx\":(\"react\",\"React\"),\"sh\":(\"shell\",\"Shell\"),\"bash\":(\"shell\",\"Shell\"),\n \"css\":(\"css\",\"CSS\"),\"md\":(\"markdown\",\"Markdown\"),\"yml\":(\"yaml\",\"YAML\"),\"yaml\":(\"yaml\",\"YAML\"),\n \"sql\":(\"sql\",\"SQL\"),\"xml\":(\"xml\",\"XML\"),\"php\":(\"php\",\"PHP\"),\"java\":(\"java\",\"Java\"),\"c\":(\"c\",\"C\"),\n \"cpp\":(\"cpp\",\"C++\"),\"go\":(\"go\",\"Go\"),\"rs\":(\"rust\",\"Rust\"),\"txt\":(\"text\",\"Text\")}\nSHEBANG = {\"python\":(\"python\",\"Python\"),\"node\":(\"node\",\"Node.js\"),\"bash\":(\"shell\",\"Shell\"),\"sh\":(\"shell\",\"Shell\")}\n\ndef detect(name, text, force=\"\"):\n    if force:\n        return next((v for v in EXT.values() if v[0] == force), (force, force.upper()))\n    ext = name.rsplit(\".\", 1)[-1].lower() if \".\" in name else \"\"\n    if ext in EXT: return EXT[ext]\n    if text.startswith(\"#!\"):\n        for k, v in SHEBANG.items():\n            if k in text.split(\"\\n\", 1)[0]: return v\n    return (\"text\", \"Text\")\n\nimport re\ndef walk(ns, path=()):\n    for n in ns:\n        yield n, path + (n[\"id\"],)\n        yield from walk(n.get(\"children\", []), path + (n[\"id\"],))\n\ndef find_node(d, ref):\n    \"\"\"ref = menu id, or a label path like 'CodeCraft/Web/Portal' (EN/BN/id, case-insensitive). -> (node, [id path]) or (None, None)\"\"\"\n    ref = ref.strip()\n    for n, p in walk(d[\"menu\"]):\n        if n[\"id\"] == ref: return n, list(p)\n    segs = [s.strip().lower() for s in ref.strip(\"/\").split(\"/\") if s.strip()]\n    if not segs: return None, None\n    def go(ns, sg, path):\n        for n in ns:\n            if sg[0] in (n[\"id\"].lower(), (n.get(\"en\") or \"\").lower(), (n.get(\"bn\") or \"\").lower()):\n                if len(sg) == 1: return n, path + [n[\"id\"]]\n                r = go(n.get(\"children\", []), sg[1:], path + [n[\"id\"]])\n                if r[0]: return r\n        return None, None\n    r = go(d[\"menu\"], segs, [])\n    if r[0]: return r\n    root = next((n for n in d[\"menu\"] if n[\"id\"] == \"codecraft\"), None)   # 'Web/Portal' means CodeCraft/Web/Portal\n    return go(root.get(\"children\", []), segs, [\"codecraft\"]) if root else (None, None)\n\ndef ensure_root(d):\n    root = next((n for n in d[\"menu\"] if n[\"id\"] == \"codecraft\"), None)\n    if not root:\n        root = {\"id\": \"codecraft\", \"bn\": \"কোডক্রাফ্ট\", \"en\": \"CodeCraft\", \"icon\": \"❮❯\", \"open\": True, \"view\": {\"type\": \"codes\"}, \"children\": []}\n        k = next((j for j, n in enumerate(d[\"menu\"]) if n[\"id\"] == \"registry\"), len(d[\"menu\"])); d[\"menu\"].insert(k, root)\n    root.setdefault(\"children\", []); return root\n\ndef ensure_chain(d, parent, ppath, names, bns=()):\n    \"\"\"Create (or reuse, matched by name) nested submenus under parent. -> (deepest node, id path)\"\"\"\n    ids = {n[\"id\"] for n, _ in walk(d[\"menu\"])}\n    for k, name in enumerate(names):\n        sib = parent.setdefault(\"children\", [])\n        hit = next((c for c in sib if name.lower() in ((c.get(\"en\") or \"\").lower(), (c.get(\"bn\") or \"\").lower())), None)\n        if not hit:\n            bn = bns[k].strip() if k < len(bns) and bns[k].strip() else name\n            base = \"c-\" + (re.sub(r\"[^a-z0-9]+\", \"-\", name.lower()).strip(\"-\") or \"m\"); nid = base; i = 2\n            while nid in ids: nid = f\"{base}-{i}\"; i += 1\n            ids.add(nid)\n            hit = {\"id\": nid, \"bn\": bn, \"en\": name, \"view\": {\"type\": \"codes\", \"filter\": {\"menu_path\": nid}}}\n            sib.append(hit)\n        parent = hit; ppath = ppath + [hit[\"id\"]]\n    return parent, ppath\n\ndef normalize(d):\n    \"\"\"Upgrade older data: language nodes filter by menu_path; entries get a menu_path.\"\"\"\n    root = ensure_root(d)\n    for c in root[\"children\"]:\n        f = c.get(\"view\", {}).get(\"filter\", {})\n        if \"lang\" in f: c[\"view\"][\"filter\"] = {\"menu_path\": c[\"id\"]}\n    for it in d[\"codes\"]:\n        it.setdefault(\"menu_path\", [\"codecraft\", \"c-\" + it[\"lang\"]])\n    return d\n```\n\n---\n\nএটা কোনো ত্রুটি নয়। আমার ডিজাইনে `title` বাধ্যতামূলক আর্গুমেন্ট ছিল, আর আপনি কোনো শিরোনাম না দিয়ে চালিয়েছেন। তবে আপনি প্রশ্নোত্তর ধরনের ইন্টারঅ্যাকটিভ মোড আশা করেছিলেন বলে মনে হচ্ছে, তাই সেটা যোগ করে দিয়েছি।\n\nএখন আর্গুমেন্ট ছাড়া চালালে একটি একটি করে জিজ্ঞেস করবে। ঐচ্ছিক ঘরে শুধু Enter চাপলেই হয়:\n\n```\n./add_task.py        # শিরোনাম (EN/BN), বিবরণ, অগ্রাধিকার, শেষ তারিখ, বিভাগ, ট্যাগ\n./add_note.py        # শিরোনাম, বিবরণ, বিভাগ, ট্যাগ, পিন\n./add_audit.py       # শিরোনাম, ফলাফল, লক্ষ্য, পর্যবেক্ষণ, অডিটর, সম্পর্কিত আইডি\n./complete_task.py   # খোলা টাস্কের তালিকা দেখিয়ে আইডি চাইবে\n```\n\nএকবারে দিতে চাইলে আগের মতোই চলবে:\n\n```\n./add_task.py \"Fix login\" --bn \"লগইন ঠিক করা\" --priority high --due 2026-10-05\n```\n\nআপডেট হয়েছে `_lib.py`, `add_task.py`, `add_note.py`, `add_audit.py` ও `complete_task.py`। এই পাঁচটি ফাইল আপনার ফোল্ডারে রিপ্লেস করুন, `data.json` ছোঁয়ার দরকার নেই। প্রতিটি রান শেষে `./run.sh check` চালিয়ে ডাটা যাচাই করে নিতে পারেন।\n\n---\n\n## V1.3\n\n*CodeCraft*\n\n`index.html`\n```\n<!DOCTYPE html>\n<html lang=\"bn\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>MJ Ahmad — Registry</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#F3F5F2;--pan:#FFFFFF;--ink:#16211E;--mut:#5F6E69;--line:#D9DFDB;--pine:#0F4C42;--brass:#B8862B;--ok:#2E7D4F;--warn:#B8862B;--bad:#B3412E;--sel:#E3EEEA;--r:6px}\n@media(prefers-color-scheme:dark){:root{--bg:#0F1514;--pan:#161E1C;--ink:#E6ECE9;--mut:#93A29C;--line:#26332F;--pine:#5FB59F;--brass:#D4A74A;--ok:#5DB985;--warn:#D4A74A;--bad:#E1705B;--sel:#1E2D29}}\n*{box-sizing:border-box;margin:0}\nhtml,body{height:100%}\nbody{font-family:\"Hind Siliguri\",\"Noto Sans Bengali\",system-ui,sans-serif;background:var(--bg);color:var(--ink);display:flex;flex-direction:column;font-size:15px;line-height:1.5}\n:focus-visible{outline:2px solid var(--brass);outline-offset:2px}\n#splash{position:fixed;inset:0;z-index:99;background:var(--pine);color:#F3F5F2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;cursor:pointer;transition:opacity .5s}\n#splash.out{opacity:0;pointer-events:none}\n#splash img{width:96px;height:96px;object-fit:contain}\n#splash h1{font-size:34px;font-weight:700;letter-spacing:.5px}\n#splash p{opacity:.8}\n#splash i{display:block;height:2px;width:0;background:var(--brass);animation:bar var(--ms,1.8s) linear forwards}\n@keyframes bar{to{width:180px}}\nheader{display:flex;align-items:center;gap:12px;padding:10px 16px;background:var(--pine);color:#F3F5F2;flex:none}\nheader img{width:36px;height:36px;object-fit:contain}\nheader h1{font-size:18px;font-weight:700;line-height:1.2}\nheader small{display:block;opacity:.8;font-size:12px}\n#q{margin-left:auto;width:min(320px,45%);padding:7px 10px;border-radius:var(--r);border:1px solid #ffffff44;background:#ffffff1c;color:#fff;font:inherit}\n#q::placeholder{color:#ffffffaa}\n#burger{display:none;background:none;border:0;color:#fff;font-size:22px}\n.main{flex:1;display:flex;min-height:0}\nnav{width:290px;flex:none;overflow:auto;background:var(--pan);border-right:1px solid var(--line);padding:10px 6px}\nnav ul{list-style:none;padding:0}\nnav ul ul{margin-left:14px;border-left:1px solid var(--line);padding-left:4px}\n.node{display:flex;align-items:center;gap:6px;padding:6px 8px;border-radius:var(--r);cursor:pointer;user-select:none}\n.node:hover{background:var(--sel)}\n.node.act{background:var(--sel);color:var(--pine);font-weight:600;box-shadow:inset 3px 0 var(--brass)}\n.chev{width:16px;text-align:center;color:var(--mut);transition:transform .15s;flex:none}\n.open>.node .chev{transform:rotate(90deg)}\nnav li>ul{display:none}nav li.open>ul{display:block}\n.ic{width:18px;text-align:center;flex:none}\n.lb{flex:1;min-width:0}.lb small{display:block;color:var(--mut);font-size:11.5px;line-height:1.2;font-weight:400}\n.cnt{font-size:11.5px;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:0 7px;color:var(--mut)}\nsection#view{flex:1;overflow:auto;padding:20px 24px}\nh2{font-size:22px;margin-bottom:2px}.sub{color:var(--mut);margin-bottom:14px}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-bottom:22px}\n.stat{background:var(--pan);border:1px solid var(--line);border-radius:var(--r);padding:12px;cursor:pointer}\n.stat b{font-size:28px;display:block;line-height:1.1}.stat span{color:var(--mut);font-size:13px}\n.stat.bad b{color:var(--bad)}\n.bar{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}\n.chip{border:1px solid var(--line);background:var(--pan);color:var(--ink);border-radius:16px;padding:2px 12px;font:inherit;font-size:13px;cursor:pointer}\n.chip.on{background:var(--pine);color:#fff;border-color:var(--pine)}\n.row{display:grid;grid-template-columns:132px 1fr auto;gap:12px;align-items:center;background:var(--pan);border:1px solid var(--line);border-radius:var(--r);padding:9px 12px;margin-bottom:6px;cursor:pointer}\n.row:hover{border-color:var(--pine)}\n.id{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;color:var(--pine)}\n.tt small{display:block;color:var(--mut);font-size:12.5px}\n.b{display:inline-block;font-size:12px;border-radius:4px;padding:0 7px;border:1px solid var(--line);margin-left:4px;white-space:nowrap}\n.b.todo,.b.low,.b.pass{color:var(--ok)}.b.doing,.b.medium,.b.warning{color:var(--warn)}.b.high,.b.urgent,.b.fail{color:var(--bad)}.b.done{color:var(--mut)}\n.empty{padding:40px 0;color:var(--mut);text-align:center}\n#modal{position:fixed;inset:0;background:#0008;display:none;z-index:50;justify-content:flex-end}\n#modal.on{display:flex}\n#modal .p{width:min(520px,100%);background:var(--pan);height:100%;overflow:auto;padding:22px}\n#modal dl{display:grid;grid-template-columns:110px 1fr;gap:6px 10px;margin:14px 0}\n#modal dt{color:var(--mut)}#modal dd{margin:0;word-break:break-word}\n#modal .lnk{color:var(--pine);cursor:pointer;text-decoration:underline;font-family:ui-monospace,monospace;font-size:13px;margin-right:8px}\n.hist{border-left:2px solid var(--line);padding-left:12px;margin-top:8px;font-size:13px;color:var(--mut)}\n.hist div{margin-bottom:6px}\n.x{float:right;background:none;border:0;font-size:22px;color:var(--mut);cursor:pointer}\nfooter{flex:none;padding:8px 16px;background:var(--pan);border-top:1px solid var(--line);color:var(--mut);font-size:12.5px;display:flex;flex-wrap:wrap;gap:6px 18px;justify-content:space-between}\n@media(max-width:820px){#burger{display:block}nav{position:fixed;top:56px;bottom:0;left:0;z-index:40;transform:translateX(-100%);transition:transform .2s;width:290px}nav.on{transform:none}.row{grid-template-columns:1fr}section#view{padding:14px}}\n.lang{display:flex;border:1px solid #ffffff55;border-radius:var(--r);overflow:hidden;flex:none}\n.lang button{background:none;border:0;color:#fff;padding:5px 11px;font:inherit;font-size:13px;font-weight:600;cursor:pointer;opacity:.75}\n.lang button+button{border-left:1px solid #ffffff55}\n.lang button.on{background:var(--brass);opacity:1}\n#splash .tg{font-style:italic;max-width:420px;text-align:center;font-size:13px;opacity:.65;padding:0 20px}\nfooter{gap:8px;flex-direction:column;align-items:stretch;max-height:45vh;overflow:auto}\nfooter a{color:var(--pine);text-decoration:none;font-weight:500}footer a:hover{text-decoration:underline}\n.fl{display:flex;flex-wrap:wrap;gap:6px 20px}\nfooter summary{cursor:pointer;color:var(--ink);font-weight:500}\n.cm{display:grid;grid-template-columns:200px 1fr;gap:4px 12px;padding:4px 0;border-bottom:1px dashed var(--line)}\n.cm code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;color:var(--pine);cursor:pointer;word-break:break-all}\n.fq{font-style:italic;color:var(--ink)}\n@media(max-width:820px){.cm{grid-template-columns:1fr}#q{width:34%}}\n.lg{background:var(--lc,#6B7B76);color:#fff;font-size:12px;font-weight:700;border-radius:4px;padding:1px 8px;letter-spacing:.4px;white-space:nowrap;align-self:flex-start}\n.row .lg{margin-left:4px}\n.l-html{--lc:#D8552B}.l-json{--lc:#A38F1A}.l-python{--lc:#3776AB}.l-node{--lc:#3F8A36}.l-shell{--lc:#3E8E3E}.l-css{--lc:#2965F1}.l-ts{--lc:#3178C6}.l-react{--lc:#1F8EA8}.l-markdown{--lc:#5B6B8C}.l-sql{--lc:#8A5AA8}\n.cc{background:var(--pan);border:1px solid var(--line);border-left:4px solid var(--lc,#6B7B76);border-radius:var(--r);margin-bottom:14px;overflow:hidden}\n.cch{display:flex;gap:12px;align-items:flex-start;padding:10px 12px}\n.ct{flex:1;min-width:0}.ct small{display:block;color:var(--mut)}\n.ca{display:flex;gap:6px}\n.ca button,.tg2{border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:var(--r);padding:3px 12px;font:inherit;font-size:13px;cursor:pointer}\n.ca button:hover,.tg2:hover{border-color:var(--pine);color:var(--pine)}\n.tg2{margin:8px 12px 10px}\n.cb{display:flex;background:#0F1917;color:#D8E4DF;font:12.5px/1.6 ui-monospace,Menlo,Consolas,monospace;overflow:auto;position:relative;max-height:70vh}\n.cb pre{margin:0}.cb .gt{padding:10px 10px 10px 12px;color