#!/usr/bin/env python3
"""MJ Node core: nodes tree, users (PBKDF2), hash-chained ledger, rules, scores, sealing."""
import json, os, sys, shutil, hashlib, hmac, secrets, base64, getpass
from datetime import datetime
HERE = os.path.dirname(os.path.abspath(__file__)); NET = os.path.join(HERE, "net.json")
LV = [("CEN","Central","কেন্দ্র"),("DIV","Division","বিভাগ"),("DST","District","জেলা"),("UPZ","Upazila","উপজেলা"),
      ("UNI","Union","ইউনিয়ন"),("VIL","Village","গ্রাম"),("PAR","Para/Mohalla","পাড়া/মহল্লা"),("TIM","Team","টিম")]
ITER = 200000
RULES = {"w": {"task": 35, "dist": 25, "report": 20, "eval": 20}, "min_reports": 4}
def now(): return datetime.now().astimezone().isoformat(timespec="seconds")
def die(m): print("ERROR:", m, file=sys.stderr); sys.exit(1)
def load():
    if not os.path.exists(NET): die("net.json missing — run: ./run.sh init \"Name\"")
    with open(NET, encoding="utf-8") as f: return json.load(f)
def save(n):
    if os.path.exists(NET): shutil.copy(NET, NET + ".bak")
    with open(NET + ".tmp", "w", encoding="utf-8") as f: json.dump(n, f, ensure_ascii=False, indent=1)
    os.replace(NET + ".tmp", NET)
def sha(s): return hashlib.sha256(s.encode()).hexdigest()
def canon(o): return json.dumps(o, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
def ehash(e): return sha(canon({k: v for k, v in e.items() if k != "hash"}))
def node(n, i): return next((x for x in n["nodes"] if x["id"] == i), None)
def subtree(n, i):
    out = [i]
    for x in n["nodes"]:
        if x["parent"] == i: out += subtree(n, x["id"])
    return out
def ancestors(n, i):
    out = []; p = node(n, i)["parent"]
    while p: out.append(p); p = node(n, p)["parent"]
    return out
def kdf(pw, salt): return hashlib.pbkdf2_hmac("sha256", pw.encode(), bytes.fromhex(salt), ITER, 64).hex()
def new_user(n, nid, name):
    """One leader account per node; password shown once, only the derived key is stored."""
    pw = secrets.token_urlsafe(9); salt = secrets.token_hex(16)
    n["users"] = [u for u in n["users"] if u["id"] != nid] + [{"id": nid, "node": nid, "name": name, "salt": salt, "key": kdf(pw, salt)}]
    return pw
def auth(n, uid):
    u = next((x for x in n["users"] if x["id"] == uid.strip().upper()), None)
    pw = os.environ.get("MJ_PASS") or getpass.getpass(f"Password for {uid}: ")
    if not u or not hmac.compare_digest(kdf(pw, u["salt"]), u["key"]): die("authentication failed")
    return u
def entry(n, nid, kind, actor, data, ref=""):
    ch = [e for e in n["ledger"] if e["node"] == nid]
    e = {"id": f"LED-{len(n['ledger'])+1:06d}", "at": now(), "node": nid, "kind": kind, "actor": actor, "ref": ref, "data": data,
         "prev": ch[-1]["hash"] if ch else "0" * 64}
    e["hash"] = ehash(e); return e
def allowed(n, e):
    k, nd, a, d = e["kind"], e["node"], e["actor"], e["data"]
    if k == "genesis": return ""
    u = next((x for x in n["users"] if x["id"] == a), None)
    L = lambda i: next((x for x in n["ledger"] if x["id"] == i), None)
    if not u or u["node"] != nd: return "actor must act for own node"
    if k == "anchor" and node(n, nd)["level"] != 0: return "only central can anchor"
    if k == "task" and d["to"] not in subtree(n, nd)[1:]: return "task target must be a descendant"
    if k == "taskdone":
        t = L(e["ref"])
        if not t or t["kind"] != "task" or t["data"]["to"] != nd: return "not your task"
    if k == "witness":
        t = L(e["ref"])
        if not t or t["kind"] != "dist": return "unknown distribution entry"
        if nd == t["node"] or not (nd in ancestors(n, t["node"]) or node(n, nd)["parent"] == node(n, t["node"])["parent"]): return "witness must be an ancestor or sibling node"
    if k == "eval" and (d["of"] not in subtree(n, nd)[1:] or not 0 <= d["score"] <= 100 or not d["basis"] or any(not L(b) or L(b)["node"] not in subtree(n, d["of"]) for b in d["basis"])):
        return "eval needs a descendant, score 0-100 and basis entries that belong to the evaluated node"
    if k in ("node", "reset") and d["id"] not in subtree(n, nd)[1:]: return "only an ancestor may do this"
    return ""
def scores(n):
    W = n["rules"]["w"]; out = {}
    for nd in n["nodes"]:
        i = nd["id"]; L = [e for e in n["ledger"] if e["node"] == i]; parts = {}
        T = [e for e in n["ledger"] if e["kind"] == "task" and e["data"]["to"] == i]; D = {e["ref"]: e for e in L if e["kind"] == "taskdone"}
        if T: parts["task"] = sum(1 for t in T if t["id"] in D and D[t["id"]]["at"][:10] <= t["data"]["due"]) / len(T)
        S = [e for e in L if e["kind"] == "dist"]; wit = {e["ref"] for e in n["ledger"] if e["kind"] == "witness"}
        if S: parts["dist"] = sum(1 for e in S if e["id"] in wit) / len(S)
        parts["report"] = min(1, sum(1 for e in L if e["kind"] == "report") / n["rules"]["min_reports"])
        V = [e["data"]["score"] for e in n["ledger"] if e["kind"] == "eval" and e["data"]["of"] == i]
        if V: parts["eval"] = sum(V) / len(V) / 100
        tw = sum(W[k] for k in parts); out[i] = round(sum(W[k] * v for k, v in parts.items()) / tw * 100) if tw else None
    return out
def seal(key_hex, plain):
    key = bytes.fromhex(key_hex); nonce = secrets.token_bytes(16)
    ks = b"".join(hmac.new(key[:32], nonce + i.to_bytes(4, "big"), "sha256").digest() for i in range((len(plain) + 31) // 32))[:len(plain)]
    ct = (int.from_bytes(plain, "big") ^ int.from_bytes(ks, "big")).to_bytes(len(plain), "big")
    b = lambda x: base64.b64encode(x).decode()
    return {"n": b(nonce), "c": b(ct), "m": b(hmac.new(key[32:], nonce + ct, "sha256").digest())}

#!/usr/bin/env python3
"""./run.sh init "Central Head Name"
./run.sh node --parent DIV-0001 --en "Savar" --bn "সাভার" --leader "Name" [--postcode 1340]   (level = parent level + 1)
./run.sh node --reset UPZ-0002        (new password for a node leader; only an ancestor may do it)
Actors authenticate with their user ID (= their node ID); password via prompt or MJ_PASS env."""
import argparse
from nodelib import *
a = argparse.ArgumentParser(); a.add_argument("--init", default=""); a.add_argument("--parent", default=""); a.add_argument("--en", default="")
a.add_argument("--bn", default=""); a.add_argument("--leader", default=""); a.add_argument("--postcode", default=""); a.add_argument("--reset", default="")
a.add_argument("--as", dest="uid", default=os.environ.get("MJ_USER", "")); x = a.parse_args()
if x.init:
    if os.path.exists(NET): die("net.json already exists")
    n = {"rules": RULES, "levels": LV, "counters": {"CEN": 1}, "nodes": [{"id": "CEN-0001", "level": 0, "parent": "", "en": "Bangladesh Central", "bn": "বাংলাদেশ কেন্দ্রীয়", "leader": x.init, "postcode": "", "created_at": now()}], "users": [], "ledger": []}
    pw = new_user(n, "CEN-0001", x.init); n["ledger"].append(entry(n, "CEN-0001", "genesis", "CEN-0001", {"rules": RULES})); save(n)
    print(f"✔ Central created.\n  User ID : CEN-0001\n  Password: {pw}   (shown once — keep it safe)"); sys.exit()
n = load(); u = auth(n, x.uid or input("Your user ID: "))
if x.reset:
    t = node(n, x.reset.upper()) or die("node not found"); e = entry(n, u["node"], "reset", u["id"], {"id": t["id"]}); r = allowed(n, e)
    if r: die(r)
    pw = new_user(n, t["id"], t["leader"]); n["ledger"].append(e); save(n); print(f"✔ New password for {t['id']}: {pw}"); sys.exit()
p = node(n, x.parent.upper()) or die("--parent node not found")
if p["level"] >= 7: die("teams are the lowest level")
lv = p["level"] + 1; pf = LV[lv][0]; n["counters"][pf] = n["counters"].get(pf, 0) + 1; nid = f"{pf}-{n['counters'][pf]:04d}"
if not (x.en and x.leader): die("--en and --leader are required")
n["nodes"].append({"id": nid, "level": lv, "parent": p["id"], "en": x.en, "bn": x.bn or x.en, "leader": x.leader, "postcode": x.postcode, "created_at": now()})
e = entry(n, u["node"], "node", u["id"], {"id": nid, "en": x.en, "leader": x.leader}); r = allowed(n, e)
if r: die(r + f" (you are {u['node']})")
pw = new_user(n, nid, x.leader); n["ledger"].append(e); save(n)
print(f"✔ {LV[lv][1]} node {nid} under {p['id']}\n  User ID : {nid}\n  Password: {pw}   (shown once)")

#!/usr/bin/env python3
"""Checks every hash chain, sequence, time order, every rule, anchors; prints the score tree. --anchor = Central records all chain heads."""
import argparse
from nodelib import *
a = argparse.ArgumentParser(); a.add_argument("--anchor", action="store_true"); a.add_argument("--as", dest="uid", default=os.environ.get("MJ_USER", "")); x = a.parse_args()
n = load(); errs = []; prev = {}; last = ""
for k, e in enumerate(n["ledger"], 1):
    if e["id"] != f"LED-{k:06d}": errs.append(f"{e['id']}: sequence gap")
    if e["at"] < last: errs.append(f"{e['id']}: time goes backwards")
    last = e["at"]
    if e["prev"] != prev.get(e["node"], "0" * 64) or ehash(e) != e["hash"]: errs.append(f"{e['id']}: CHAIN BROKEN (edited or removed entry)")
    prev[e["node"]] = e["hash"]; r = allowed(n, e)
    if r: errs.append(f"{e['id']}: {r}")
    if e["kind"] == "anchor":
        errs += [f"{e['id']}: anchored head of {nd} no longer in chain" for nd, h in e["data"]["heads"].items() if not any(y["hash"] == h for y in n["ledger"] if y["node"] == nd)]
if errs: print("✘ PROBLEMS:"); [print("  -", m) for m in errs]; sys.exit(1)
if x.anchor:
    u = auth(n, x.uid or input("Central user ID: ")); e = entry(n, u["node"], "anchor", u["id"], {"heads": dict(prev)}); r = allowed(n, e)
    if r: die(r)
    n["ledger"].append(e); save(n); print("✔ anchored", e["id"])
S = scores(n)
def show(i, d=0):
    nd = node(n, i); print("  " * d + f"{LV[nd['level']][0]} {i} {nd['en']} / {nd['bn']} — {nd['leader']}  score: {S[i] if S[i] is not None else '—'}")
    [show(c["id"], d + 1) for c in n["nodes"] if c["parent"] == i]
show("CEN-0001"); print(f"✔ OK — {len(n['nodes'])} nodes, {len(n['ledger'])} entries, all chains and rules verified")

#!/usr/bin/env python3
"""Builds sites/<NODE-ID>/index.html for every node. Each page contains ONLY that node's subtree, encrypted with its leader's key."""
import subprocess
from nodelib import *
if subprocess.call([sys.executable, os.path.join(HERE, "verify.py")], stdout=subprocess.DEVNULL): die("verify failed — run ./run.sh verify")
n = load(); S = scores(n); T = open(os.path.join(HERE, "site.tpl"), encoding="utf-8").read()
for u in n["users"]:
    sub = subtree(n, u["node"]); ids = set(sub)
    P = {"root": u["node"], "lv": LV, "rules": n["rules"], "built": now(), "anc": [{k: node(n, i)[k] for k in ("id", "en", "bn", "level")} for i in ancestors(n, u["node"])],
         "nodes": [x for x in n["nodes"] if x["id"] in ids], "scores": {i: S[i] for i in sub},
         "ledger": [e for e in n["ledger"] if e["node"] in ids or e["kind"] == "anchor"]}
    pk = {"u": u["id"], "s": base64.b64encode(bytes.fromhex(u["salt"])).decode(), **seal(u["key"], json.dumps(P, ensure_ascii=False).encode())}
    os.makedirs(os.path.join(HERE, "sites", u["id"]), exist_ok=True)
    open(os.path.join(HERE, "sites", u["id"], "index.html"), "w", encoding="utf-8").write(T.replace("__PACKS__", json.dumps([pk])).replace("__NODE__", u["id"]))
print(f"✔ built {len(n['users'])} node sites in sites/  (net.json stays private — never publish it)")

#!/usr/bin/env bash
# ./run.sh init "Name" | node ... | log ... | verify [--anchor] | build | serve
cd "$(dirname "$0")"; c="$1"; shift
case "$c" in
  init) python3 add_node.py --init "$@" ;;
  node) python3 add_node.py "$@" && python3 build.py ;;
  log) python3 log.py "$@" && python3 build.py ;;
  verify) python3 verify.py "$@" ;;
  build) python3 build.py ;;
  serve) echo "Open http://localhost:8001"; python3 -m http.server 8001 ;;
  *) echo "usage: ./run.sh init|node|log|verify|build|serve" ;;
esac

